def simple_bit_rotate_right(data, total_bits):
    """Rotate entire buffer right by total_bits bits"""
    length = len(data)
    if length == 0:
        return data

    total_bits_max = length * 8
    total_bits = total_bits % total_bits_max

    if total_bits == 0:
        return data

    val = int.from_bytes(data, 'big')
    rotated = ((val >> total_bits) | (val << (total_bits_max - total_bits))) & ((1 << total_bits_max) - 1)
    return rotated.to_bytes(length, 'big')

target = bytes([
    0xad, 0xa9, 0x19, 0x19, 0x99, 0xb5, 0xa1, 0xbb,
    0xb9, 0xa1, 0x87, 0x95, 0xdd, 0xdd, 0x87, 0xa1,
    0xa7, 0xa7, 0xb1, 0x8b, 0x39, 0xf3, 0x03, 0xfb,
    0xe9
])

xored = bytes([b ^ 0x23 for b in target])
print(f"XORed target: {xored.hex()}")

# Try different rotation amounts
print("\n--- Reverse rotation then decode ---")
for rot in range(0, 200):
    rotated = simple_bit_rotate_right(xored, rot)
    try:
        decoded = rotated.decode('ascii')
        if decoded.startswith('kalmar') or decoded.startswith('flag') or '{' in decoded:
            print(f"Rotation {rot}: {decoded}")
    except:
        pass

# Also try with XOR after rotation
print("\n--- Reverse rotation then XOR then decode ---")
for rot in range(0, 200):
    rotated = simple_bit_rotate_right(target, rot)
    xored_after = bytes([b ^ 0x23 for b in rotated])
    try:
        decoded = xored_after.decode('ascii')
        if 'kalmar' in decoded or 'flag' in decoded or decoded.startswith('k'):
            print(f"Rotation {rot}: {decoded}")
    except:
        pass

# Let me also check if any rotation gives printable ASCII
print("\n--- Any rotation giving printable ASCII ---")
for rot in range(0, 200):
    rotated = simple_bit_rotate_right(xored, rot)
    if all(32 <= b < 127 for b in rotated):
        print(f"Rotation {rot}: {rotated}")
